+import {AFTER_RENDER_SEQUENCES_TO_ADD, LView} from '../interfaces/view';
+
+export function addAfterRenderSequencesForView(lView: LView) {
+  if (lView[AFTER_RENDER_SEQUENCES_TO_ADD] !== null) {
