commit edc1740d7e7f0296c719c7176c24031f55ae1487
Author: JoostK <joost.koehoorn@gmail.com>
Date:   Sun Mar 10 22:05:30 2024 +0100

restructure logic in `isCssClassMatching` function (#54800) The logic in `isCssClassMatching` is only interested in two areas in the attributes: implicit attributes and the `AttributeMarker.Classes` area, with the first area only of interest for projection matching, not directive matching. This commit splits these two searches to make this more apparent. PR Close #54800



diff --git a/packages/core/src/render3/node_selector_matcher.ts b/packages/core/src/render3/node_selector_matcher.ts
index b7ec52aa8d..f5031e754f 100644
--- a/packages/core/src/render3/node_selector_matcher.ts
+++ b/packages/core/src/render3/node_selector_matcher.ts

@@ -33,37 +33,30 @@ function isCssClassMatching(
       assertEqual(
           cssClassToMatch, cssClassToMatch.toLowerCase(), 'Class name expected to be lowercase.');
   let i = 0;
-  // Indicates whether we are processing value from the implicit
-  // attribute section (i.e. before the first marker in the array).
-  let isImplicitAttrsSection = true;
-  while (i < attrs.length) {
-    let item = attrs[i++];
-    if (typeof item === 'string' && isImplicitAttrsSection) {
-      const value = attrs[i++] as string;
-      if (isProjectionMode && item === 'class') {
-        // We found a `class` attribute in the implicit attribute section,
-        // check if it matches the value of the `cssClassToMatch` argument.
-        if (classIndexOf(value.toLowerCase(), cssClassToMatch, 0) !== -1) {
-          return true;
-        }
-      }
-    } else if (item === AttributeMarker.Classes) {
-      if (!isProjectionMode && isInlineTemplate(tNode)) {
-        // Matching directives (i.e. when not matching for projection mode) should not consider the
-        // class bindings that are present on inline templates, as those class bindings only target
-        // the root node of the template, not the template itself.
-        return false;
+  if (isProjectionMode) {
+    for (; i < attrs.length && typeof attrs[i] === 'string'; i += 2) {
+      // Search for an implicit `class` attribute and check if its value matches `cssClassToMatch`.
+      if (attrs[i] === 'class' &&
+          classIndexOf((attrs[i + 1] as string).toLowerCase(), cssClassToMatch, 0) !== -1) {
+        return true;
       }
-      // We found the classes section. Start searching for the class.
-      while (i < attrs.length && typeof (item = attrs[i++]) == 'string') {
-        // while we have strings
-        if (item.toLowerCase() === cssClassToMatch) return true;
+    }
+  } else if (isInlineTemplate(tNode)) {
+    // Matching directives (i.e. when not matching for projection mode) should not consider the
+    // class bindings that are present on inline templates, as those class bindings only target
+    // the root node of the template, not the template itself.
+    return false;
+  }
+
+  // Resume the search for classes after the `Classes` marker.
+  i = attrs.indexOf(AttributeMarker.Classes, i);
+  if (i > -1) {
+    // We found the classes section. Start searching for the class.
+    let item: TAttributes[number];
+    while (++i < attrs.length && typeof (item = attrs[i]) === 'string') {
+      if (item.toLowerCase() === cssClassToMatch) {
+        return true;
       }
-      return false;
-    } else if (typeof item === 'number') {
-      // We've come across a first marker, which indicates
-      // that the implicit attribute section is over.
-      isImplicitAttrsSection = false;
     }
   }
   return false;

commit a8d4eb8c25e5c1462f54dec4c1464b269e0e3bc6
Author: cexbrayat <cedric@ninja-squad.com>
Date:   Thu Oct 17 08:09:14 2024 +0200

test EventEmitter completion on destroy with outputToObservable (#58239) A unit test has been added to check that `EventEmitter` properly completes upon component/directive destrouction when used with `outputToObservable`. It explains why `destroyRef` has to be injected in `EventEmitter` in the first place. PR Close #58239



diff --git a/packages/core/rxjs-interop/test/output_to_observable_spec.ts b/packages/core/rxjs-interop/test/output_to_observable_spec.ts
index b178c29819..80cd5b32a9 100644
--- a/packages/core/rxjs-interop/test/output_to_observable_spec.ts
+++ b/packages/core/rxjs-interop/test/output_to_observable_spec.ts

@@ -49,6 +49,30 @@ describe('outputToObservable()', () => {
     expect(subscription.closed).toBe(true);
   });

+  it('should complete EventEmitter upon directive destroy', () => {
+    const eventEmitter = TestBed.runInInjectionContext(() => new EventEmitter<number>());
+    const observable = outputToObservable(eventEmitter);
+
+    let completed = false;
+    const subscription = observable.subscribe({
+      complete: () => (completed = true),
+    });
+
+    eventEmitter.next(1);
