--- a/packages/core/primitives/event-dispatch/src/legacy_dispatcher.ts
+++ b/packages/core/primitives/event-dispatch/src/legacy_dispatcher.ts

@@ -6,4 +6,325 @@
  * found in the LICENSE file at https://angular.io/license
