+    url,
+    sameDocument,
+    historyState,
+    state,
+    key = null,
+    id = null,
+    index = -1,
+  }: {
+    url: string;
+    sameDocument: boolean;
+    historyState: unknown;
+    state?: unknown;
+    key?: string | null;
+    id?: string | null;
+    index?: number;
+  }) {
+    this.url = url;
+    this.sameDocument = sameDocument;
+    this.state = state;
+    this.historyState = historyState;
+    this.key = key;
+    this.id = id;
+    this.index = index;
+  }
